	/**
	 * Default Constructor
	 */
    public ControlService(CurrentIdentity identity,
				ApplicationContext applicationContext)  {

		this.identity		= identity;
		this.projector 		= new ControlEntityProjector( applicationContext.getBean(ProjectorRegistry.class),
										applicationContext.getBean(ControlRepository.class) );
		this.validator		= applicationContext.getBean(ControlValidator.class) ;
	}


	/**
	 * Creates the provided command.
	 *
	 * @param		command ${class.getCreateCommandAlias()}
	 * @return		Control
	 */
		public Control createControl( CreateControlCommand command ) {

		Control entity = new Control();

		// --------------------------------------
		// validate the command
		// --------------------------------------
		validator.validate( command );

            entity.setControlId( command.getControlId() );
            entity.setName( command.getName() );
            entity.setObjective( command.getObjective() );
            entity.setOwnerDepartment( command.getOwnerDepartment() );
            entity.setControlType( command.getControlType() );
            entity.setFrequency( command.getFrequency() );
            entity.setStatus( command.getStatus() );

		// ------------------------------------------
		// persist a new one
		// ------------------------------------------
		entity = projector.create(entity);

		LOGGER.info( "done creating of Control {0} ", entity.toString() );

		return entity;
	}

	/**
	 * Update the provided command.
	 * @param		command UpdateControlCommand
	 * @return		Control
	 */
	public Control updateControl( UpdateControlCommand command ) {

		Control entity = new Control();

		// --------------------------------------
		// validate
		// --------------------------------------
		validator.validate( command );

            entity.setControlId( command.getControlId() );
            entity.setName( command.getName() );
            entity.setObjective( command.getObjective() );
            entity.setOwnerDepartment( command.getOwnerDepartment() );
            entity.setPolicy( command.getPolicy() );
            entity.setControlTests( command.getControlTests() );
            entity.setEvidence( command.getEvidence() );
            entity.setRisks( command.getRisks() );
            entity.setObligations( command.getObligations() );
            entity.setProcedures( command.getProcedures() );
            entity.setIssues( command.getIssues() );
            entity.setControlType( command.getControlType() );
            entity.setFrequency( command.getFrequency() );
            entity.setStatus( command.getStatus() );

		// ------------------------------------------
		// persist an existing one
		// ------------------------------------------
		entity = projector.update(entity);

		LOGGER.info( "done saving of Control {0} ", entity.toString() );

		return entity;
	}

	/**
	 * Deletes the associatied value object
	 * @param		command DeleteControlCommand
	 */
	public void delete( DeleteControlCommand command ) {
		UUID id = null;

		// --------------------------------------
		// validate the command
		// --------------------------------------
		validator.validate( command );

		id = command.getControlId();

		// ------------------------------------------
		// delete the entity
		// ------------------------------------------
		projector.delete(id);

		LOGGER.info( "done deleting of Control {0} ", id );

	}

	/**
	 * Method to retrieve the Control via ControlFetchOneSummary
	 * @param 	summary ControlFetchOneSummary
	 * @return 	ControlFetchOneResponse
	 */
	public Control getControl( ControlFetchOneSummary summary ) {

		if( summary == null )
			throw new IllegalStateException( "ControlFetchOneSummary arg cannot be null" );

		Control entity = null;
		UUID id = summary.getControlId();

		// --------------------------------------
		// validate the fetch one summary
		// --------------------------------------
		validator.validate( summary );

		// --------------------------------------
		// find a Control using the provided id
		// --------------------------------------
		entity = projector.find( id );

		return entity;
	}


	/**
	 * Method to retrieve a collection of all Controls
	 *
	 * @return 	List<Control>
	 */
    public List<Control> getAllControl() {
		List<Control> list = projector.findAll( new FindAllControlQuery() );
		return list;
	}

	/**
	 * assign Policy on Control
	 * @param		command AssignPolicyToControlCommand
	 */
	public void assignPolicy( AssignPolicyToControlCommand command ) {
		// --------------------------------------
		// best to validate the command now
		// --------------------------------------
		validator.validate( command );

		// --------------------------------------
		// delegate to the projector
		// --------------------------------------
		projector.assignPolicy(command.getControlId(), command.getAssignment());

	}

